status, b.Shopify_Shipping_Status) end) FINAL_SHIPPING_STATUS ,b.LINE_ITEM_ID::varchar as SALEORDERITEMCODE ,d.sales_order_item_id as SALES_ORDER_ITEM_ID ,coalesce(c.awb,b.awb,d.awb) AWB ,UPPER(b.payment_gateway_names) PAYMENT_GATEWAY ,upper(coalesce(c.payment_mode,d.payment_mode,(case when replace(lower(payment_gateway),\' \',\'\') = \'cashondelivery\' then \'COD\' else \'PREPAID\' end))) Payment_Mode ,Upper(coalesce(c.Courier,d.courier)) AS COURIER ,coalesce(c.manifest_date,d.dispatch_date) AS DISPATCH_DATE ,coalesce(c.delivered_date,d.delivered_date,case when b.shopify_shipping_status like \'delivered\' then b.SHOPIFY_SHIPPING_UPDATED_DATE end) AS DELIVERED_DATE ,case when lower(coalesce(c.shipping_status,b.shopify_shipping_status, d.shipping_status)) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') and lower(c.shipping_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) AS RETURN_FLAG ,case when RETURN_FLAG = 1 and lower(b.order_status) not in (\'cancelled\') and lower(c.shipping_status) not in (\'cancelled\') then ifnull(refund_quantity,0) end returned_quantity ,case when RETURN_FLAG = 1 and lower(b.order_status) not in (\'cancelled\') and lower(c.shipping_status) not in (\'cancelled\') then ifnull(refund_value,0) end returned_sales ,case when lower(b.order_status) in (\'cancelled\') or lower(c.shipping_status) like \'%cancel%\' then quantity::int end cancelled_quantity ,b.shopify_new_customer_flag as NEW_CUSTOMER_FLAG ,Upper(b.shopify_acquisition_product) as acquisition_product ,case when lower(coalesce(c.shipping_status, b.shopify_shipping_status,d.shipping_status)) in (\'delivered\',\'delivered to origin\') then datediff(day,date(b.ORDER_TIMESTAMP),date(coalesce(c.shipping_last_update_date::datetime, b.Shopify_Shipping_Updated_Date, d.shipping_last_update_date::datetime))) when lower(coalesce(c.shipping_status, b.shopify_shipping_status,d.shipping_status)) in (\'in transit\', \'shipment created\') then datediff(day,date(b.ORDER_TIMESTAMP), getdate()) end::int as Days_in_Shipment ,b.shopify_acquisition_date AS ACQUSITION_DATE ,b.SKU_CODE ,UPPER(b.PRODUCT_NAME_FINAL) PRODUCT_NAME_FINAL ,UPPER(b.PRODUCT_CATEGORY) PRODUCT_CATEGORY ,upper(b.PRODUCT_SUB_CATEGORY) PRODUCT_SUB_CATEGORY ,b.brand ,upper(c.warehouse_name) WAREHOUSE ,coalesce(b.pincode, c.pincode) pincode ,c.shipping_status easyecom_Status ,line_item_sales ,ifnull(refund_amount_without_lineitem,0) + ifnull(Refund_Value,0) as refund_amount_without_lineitem ,discount_code from datalake_db.kaya.dwh_SHOPIFY_FACT_ITEMS b left join (select * from ( select * ,row_number()over(partition by reference_code, Marketplace_LineItem_ID, suborder_id order by last_update_date desc) rw from datalake_db.kaya.dwh_EasyEcom_FACT_ITEMS ) z where z.rw = 1 and lower(marketplace) like any (\'%shopify%\') ) c on lower(replace(b.order_name,\'#\',\'\')) = lower(c.reference_code) and b.LINE_ITEM_ID=c.Marketplace_LineItem_ID left join (select * from (select order_id ,city ,state ,saleorderitemcode ,sales_order_item_id ,shippingpackagecode ,SHIPPINGPACKAGESTATUS ,shipping_status ,order_status ,Courier ,Dispatch_Date ,Delivered_date ,Return_flag ,Return_quantity ,cancelled_quantity ,shipping_last_update_date ,days_in_shipment ,awb ,Courierstatus ,payment_method ,PAYMENT_MODE ,email ,row_number() over (partition by order_id, split_part(saleorderitemcode,\'-\',0) order by shipping_last_update_date desc) rw from datalake_db.kaya.dwh_UNICOMMERCE_FACT_ITEMS where lower(marketplace) like any (\'%shopify%\')) where rw=1 ) d on b.order_id=d.order_id and b.line_item_id=split_part(d.saleorderitemcode,\'-\',0) union all select Null as customer_id ,upper(b.SHOP_NAME) SHOP_NAME ,upper(marketplace) marketplace ,upper(marketplace) CHANNEL ,upper(marketplace) SOURCE ,upper(marketplace) PLATFORM_TRAFFIC ,b.ORDER_ID ,reference_code ,contact_num as PHONE ,customer_name as NAME ,email as EMAIL ,b.shipping_last_update_date AS SHIPPING_LAST_UPDATE_DATE ,b.SKU ,b.easyecom_sku PRODUCT_ID ,upper(PRODUCTNAME) AS PRODUCT_NAME ,CURRENCY ,upper(CITY) City ,upper(STATE) AS State ,upper(ORDER_STATUS) as Order_Status ,ORDER_DATE::date AS Order_Date ,ORDER_DATE ,SUBORDER_QUANTITY AS QUANTITY ,ifnull(SELLING_PRICE,0)-ifnull(tax,0)+ifnull(DISCOUNT,0) AS GROSS_SALES_BEFORE_TAX ,case when SUBORDER_QUANTITY*SUBORDER_MRP - (SELLING_PRICE - SHIPPING_PRICE) < 0 then 0 else SUBORDER_QUANTITY*SUBORDER_MRP - (SELLING_PRICE -SHIPPING_PRICE) end AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,SUBORDER_QUANTITY*SUBORDER_MRP as mrp_Sales ,upper(ORDER_STATUS) as OMS_Order_Status ,upper(b.Shipping_status) AS SHIPPING_STATUS ,upper( case when lower(oms_order_status) like \'%cancel%\' or lower(b.Shipping_status) like \'%cancel%\' then \'CANCELLED\' else b.shipping_status end) FINAL_SHIPPING_STATUS ,Marketplace_LineItem_ID as SALEORDERITEMCODE ,suborder_id as SALES_ORDER_ITEM_ID ,b.awb AWB ,NULL Payment_Gateway ,b.payment_mode Payment_Mode ,b.courier COURIER ,b.MANIFEST_DATE as DISPATCH_DATE ,b.DELIVERED_DATE DELIVERED_DATE ,case when lower(b.shipping_status) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,IS_REFUND AS RETURN_FLAG ,case when is_refund = 1 then suborder_quantity::int end returned_quantity ,case when RETURN_FLAG = 1 and lower(order_status) not in (\'cancelled\') then ifnull(is_refund,0) end returned_sales ,case when is_refund = 0 and lower(order_status) in (\'cancelled\') then suborder_quantity::int end cancelled_quantity ,new_customer_flag::varchar as NEW_CUSTOMER_FLAG ,NULL as ACQUISITION_PRODUCT ,Days_in_shipment AS DAYS_IN_SHIPMENT ,NULL AS ACQUSITION_DATE ,b.SKU as SKU_CODE ,upper(mapped_product_name) as PRODUCT_NAME_FINAL ,upper(mapped_category) as PRODUCT_CATEGORY ,upper(mapped_sub_category) as PRODUCT_SUB_CATEGORY ,b.mapped_brand ,upper(WAREHOUSE_NAME) WAREHOUSE ,b.pincode ,b.shipping_status easyecom_status ,selling_price line_item_sales ,null refund_amount_without_lineitem ,null as discount_code from datalake_db.kaya.dwh_EasyEcom_FACT_ITEMS b left join (select * from (select * ,row_number() over (partition by transactionid, shop_name order by 1) rw from datalake_db.kaya.dwh_kaya_GA_ORDER_BY_SOURCE_CONSOLIDATED ) where rw =1 ) GA on b.reference_code = GA.transactionid where lower(marketplace) not like (\'%shopify%\' ) UNION ALL select Null as customer_id ,upper(marketplace) shop_name ,upper(marketplace) marektplace ,upper(marketplace) AS CHANNEL ,upper(marketplace) AS SOURCE ,marketplace as PLATFORM_TRAFFIC ,ORDER_ID ,reference_code ,phone as PHONE ,name as NAME ,email as EMAIL ,shipping_last_update_date AS SHIPPING_LAST_UPDATE_DATE ,SKU ,b.PRODUCT_ID ,PRODUCT_NAME AS PRODUCT_NAME ,CURRENCY ,upper(CITY) as city ,upper(STATE) AS State ,upper(ORDER_STATUS) order_status ,ORDER_DATE::date AS Order_Date ,order_date as ORDER_TIMESTAMP ,SUBORDER_QUANTITY AS QUANTITY ,ifnull(SELLING_PRICE,0) - ifnull(tax,0) gross_sales_before_tax ,case when MRP_SALES is null or MRP_SALES = 0 then b.DISCOUNT else (MRP_SALES - b.SELLING_PRICE) end AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,ifnull(MRP_SALES,0) as MRP_SALES ,upper(ORDER_STATUS) as OMS_ORDER_STATUS ,upper(coalesce(b.shippingpackagestatus,b.shipping_status)) AS SHIPPING_STATUS ,upper(coalesce(b.shippingpackagestatus,b.shipping_status)) FINAL_SHIPPING_STATUS ,saleOrderItemCode as SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID as SALES_ORDER_ITEM_ID ,AWB ,null as payment_gateway ,upper(payment_mode) payment_mode ,upper(coalesce(COURIER, courier_aggregator)) COURIER ,DISPATCH_DATE AS DISPATCH_DATE ,delivered_date as delivered_date ,case when upper(FINAL_SHIPPING_STATUS) in (\'DELIVERED\') then 1 end AS DELIVERED_STATUS ,return_flag AS RETURN_FLAG ,case when return_flag = 1 then suborder_quantity::int end returned_quantity ,case when return_flag = 1 then selling_price::float end returned_sales ,case when return_flag = 0 and lower(order_status) in (\'cancelled\') then suborder_quantity::int end cancelled_quantity ,new_customer_flag::varchar as NEW_CUSTOMER_FLAG ,NULL as ACQUISITION_PRODUCT ,case when order_status=\'COMPLETE\' then delivered_date::date-order_date::date else current_date - order_date::Date end as days_in_shipment ,NULL AS ACQUSITION_DATE ,b.commonsku sku_code ,upper(b.product_name_final) PRODUCT_NAME_FINAL ,upper(b.Product_Category) PRODUCT_CATEGORY ,upper(b.product_sub_category) PRODUCT_SUB_CATEGORY ,null as brand ,upper(warehouse_name) warehouse ,pincode ,courierstatus ,selling_price line_item_sales ,null refund_amount_without_lineitem ,null as discount_code from datalake_db.kaya.dwh_unicommerce_fact_items b where not(lower(b.marketplace) like any (\'%shopify%\',\'%amazon%\',\'%amz%\',\'custom\')) ; create or replace table datalake_db.kaya.dwh_Final_customerID as with new_phone_numbers as ( select phone, contact_num, 19700000000 + row_number() over( order by contact_num asc ) as maple_monk_id from ( select distinct right(regexp_replace(phone, \'[^a-zA-Z0-9]+\'),10) as contact_num, phone from datalake_db.kaya.dwh_sales_consolidated_intermediate ) a ), int as ( select contact_num, email, coalesce(maple_monk_id,id2) as maple_monk_id from ( select contact_num, email, maple_monk_id, 19800000000+row_number() over(partition by maple_monk_id is NULL order by email asc ) as id2 from ( select distinct coalesce(p.contact_num,right(regexp_replace(e.contact_num, \'[^a-zA-Z0-9]+\'),10)) as contact_num, e.email, maple_monk_id from ( select phone as contact_num, email from datalake_db.kaya.dwh_sales_consolidated_intermediate ) e left join new_phone_numbers p on p.contact_num = right(regexp_replace(e.contact_num, \'[^a-zA-Z0-9]+\'),10) ) a ) b ) select contact_num, email, maple_monk_id from int where coalesce(contact_num,email) is not NULL ; create or replace table datalake_db.kaya.dwh_sales_consolidated as select coalesce(m.maple_monk_id_phone, d.maple_monk_id) as customer_id_final, min(order_date) over(partition by customer_id_final) as acquisition_date, min(case when lower(m.order_status) not in (\'cancelled\') then order_date end) over(partition by customer_id_final) as first_complete_order_date, m.*, coalesce(m.order_status, m.shipping_status) as final_status from ( select c.maple_monk_id as maple_monk_id_phone, o.* from datalake_db.kaya.dwh_sales_consolidated_intermediate o left join ( select * from ( select contact_num phone, maple_monk_id, row_number() over (partition by contact_num order by maple_monk_id asc) magic from datalake_db.kaya.dwh_Final_customerID ) where magic =1 )c on c.phone = right(regexp_replace(o.phone, \'[^a-zA-Z0-9]+\'),10) )m left join ( select distinct maple_monk_id, email from datalake_db.kaya.dwh_Final_customerID where contact_num is null )d on d.email = m.email ; ALTER TABLE datalake_db.kaya.dwh_sales_consolidated drop COLUMN new_customer_flag ; ALTER TABLE datalake_db.kaya.dwh_sales_consolidated ADD COLUMN new_customer_flag varchar(50); ALTER TABLE datalake_db.kaya.dwh_sales_consolidated ADD COLUMN new_customer_flag_month varchar(50); ALTER TABLE datalake_db.kaya.dwh_sales_consolidated drop COLUMN acquisition_product ; ALTER TABLE datalake_db.kaya.dwh_sales_consolidated ADD COLUMN acquisition_product varchar(16777216); ALTER TABLE datalake_db.kaya.dwh_sales_consolidated ADD COLUMN acquisition_SKUCODE varchar(16777216); ALTER TABLE datalake_db.kaya.dwh_sales_consolidated ADD COLUMN acquisition_PRODUCT_SUB_CATEGORY varchar(16777216); ALTER TABLE datalake_db.kaya.dwh_sales_consolidated ADD COLUMN acquisition_PRODUCT_CATEGORY varchar(16777216); ALTER TABLE datalake_db.kaya.dwh_sales_consolidated ADD COLUMN acquisition_channel varchar(16777216); ALTER TABLE datalake_db.kaya.dwh_sales_consolidated ADD COLUMN acquisition_marketplace varchar(16777216); UPDATE datalake_db.kaya.dwh_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date then \'New\' WHEN Order_Date < first_complete_order_date or first_complete_order_date is null THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date then \'Repeat\' END AS Flag FROM datalake_db.kaya.dwh_sales_consolidated)AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final AND A.order_date::date=B.Order_date::Date; UPDATE datalake_db.kaya.dwh_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\') end) THEN \'New\' WHEN new_customer_flag IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) in (\'cancelled\') end) THEN \'Yet to make completed order\' ELSE new_customer_flag END; UPDATE datalake_db.kaya.dwh_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, Order_Date, CASE WHEN Last_day(order_date, \'month\') = Last_day(first_complete_order_date, \'month\') THEN \'New\' WHEN Last_day(order_date, \'month\') < Last_day(first_complete_order_date, \'month\') or acquisition_date is null THEN \'Yet to make completed order\' WHEN Last_day(order_date, \'month\') > Last_day(first_complete_order_date, \'month\') THEN \'Repeat\' END AS Flag FROM datalake_db.kaya.dwh_sales_consolidated)AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final; UPDATE datalake_db.kaya.dwh_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\') end) THEN \'New\' ELSE new_customer_flag_month END; create or replace temporary table datalake_db.kaya.dwh_temp_source_1 AS SELECT DISTINCT customer_id_final, channel, marketplace FROM ( SELECT DISTINCT customer_id_final, order_date, source as channel, shop_name as marketplace, Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER ( partition BY customer_id_final) firstOrderdate FROM datalake_db.kaya.dwh_sales_consolidated ) res WHERE order_date=firstorderdate; UPDATE datalake_db.kaya.dwh_sales_consolidated AS a SET a.acquisition_channel=b.channel FROM datalake_db.kaya.dwh_temp_source_1 b WHERE a.customer_id_final = b.customer_id_final; UPDATE datalake_db.kaya.dwh_sales_consolidated AS a SET a.acquisition_marketplace=b.marketplace FROM datalake_db.kaya.dwh_temp_source_1 b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE datalake_db.kaya.dwh_temp_product_1 AS SELECT DISTINCT customer_id_final, product_name_final, product_category, product_sub_category, sku, Row_number() OVER (partition BY customer_id_final ORDER BY SELLING_PRICE DESC) rowid FROM ( SELECT DISTINCT customer_id_final, order_date, product_name_final, product_category, product_sub_category, sku, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate FROM datalake_db.kaya.dwh_sales_consolidated )res WHERE order_date=firstorderdate; UPDATE datalake_db.kaya.dwh_sales_consolidated AS A SET A.acquisition_product=B.product_name_final FROM ( SELECT * FROM datalake_db.kaya.dwh_temp_product_1 WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final; UPDATE datalake_db.kaya.dwh_sales_consolidated AS A SET A.acquisition_product_category=B.product_category FROM ( SELECT * FROM datalake_db.kaya.dwh_temp_product_1 WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final; UPDATE datalake_db.kaya.dwh_sales_consolidated AS A SET A.acquisition_product_sub_category=B.product_sub_category FROM ( SELECT * FROM datalake_db.kaya.dwh_temp_product_1 WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final; UPDATE datalake_db.kaya.dwh_sales_consolidated AS A SET A.acquisition_SKUCODE=B.SKU FROM ( SELECT * FROM datalake_db.kaya.dwh_temp_product_1 WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final; Create or Replace table datalake_db.kaya.dwh_sales_consolidated as select CUSTOMER_ID_FINAL ,ACQUISITION_DATE ,FIRST_COMPLETE_ORDER_DATE ,MAPLE_MONK_ID_PHONE ,CUSTOMER_ID ,SHOP_NAME ,MARKETPLACE ,CHANNEL ,SOURCE ,PLATFORM_TRAFFIC ,ORDER_ID ,REFERENCE_CODE ,PHONE ,NAME ,EMAIL ,SHIPPING_LAST_UPDATE_DATE ,SKU ,PRODUCT_ID ,PRODUCT_NAME ,CURRENCY ,CITY ,STATE ,ORDER_STATUS ,ORDER_DATE ,ORDER_TIMESTAMP ,QUANTITY ,GROSS_SALES_BEFORE_TAX ,DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE ,MRP_SALES ,OMS_ORDER_STATUS ,SHIPPING_STATUS ,FINAL_SHIPPING_STATUS ,SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID ,AWB ,PAYMENT_GATEWAY ,PAYMENT_MODE ,COURIER ,DISPATCH_DATE ,DELIVERED_DATE ,DELIVERED_STATUS ,RETURN_FLAG ,RETURNED_QUANTITY ,RETURNED_SALES ,CANCELLED_QUANTITY ,DAYS_IN_SHIPMENT ,ACQUSITION_DATE ,SKU_CODE ,PRODUCT_NAME_FINAL ,PRODUCT_CATEGORY ,PRODUCT_SUB_CATEGORY ,BRAND ,WAREHOUSE ,PINCODE ,EASYECOM_STATUS ,LINE_ITEM_SALES ,REFUND_AMOUNT_WITHOUT_LINEITEM ,DISCOUNT_CODE ,FINAL_STATUS ,NEW_CUSTOMER_FLAG ,NEW_CUSTOMER_FLAG_MONTH ,ACQUISITION_PRODUCT ,ACQUISITION_SKUCODE ,ACQUISITION_PRODUCT_SUB_CATEGORY ,ACQUISITION_PRODUCT_CATEGORY ,ACQUISITION_CHANNEL ,ACQUISITION_MARKETPLACE ,null as Return_Sales ,null as REFUND_QUANTITY ,\'Sales\' as Type ,case when uppeR(ifnull(ORDER_STATUS,\'\')) like \'%CANCEL%\' then \'YES\' else \'NO\' end as Cancelled_Status from datalake_db.kaya.dwh_sales_consolidated UNION ALL select null as CUSTOMER_ID_FINAL ,null as ACQUISITION_DATE ,null as FIRST_COMPLETE_ORDER_DATE ,null as MAPLE_MONK_ID_PHONE ,null as CUSTOMER_ID ,upper(SHOP_NAME) ,upper(SHOP_NAME) as MARKETPLACE ,Upper(FINAL_UTM_CHANNEL) AS CHANNEL ,Upper(FINAL_UTM_SOURCE) AS SOURCE ,upper(FINAL_UTM_PLATFORM_TRAFFIC) as PLATFORM_TRAFFIC ,null ORDER_ID ,order_name as REFERENCE_CODE ,null as PHONE ,null as NAME ,null as EMAIL ,null as SHIPPING_LAST_UPDATE_DATE ,SKU ,null as PRODUCT_ID ,null as PRODUCT_NAME ,null as CURRENCY ,null as CITY ,null as STATE ,uppeR(ORDER_STATUS) ORDER_STATUS ,coalesce(refund_date,order_timestamp::date) as ORDER_DATE ,coalesce(refund_date,order_timestamp::date) as ORDER_TIMESTAMP ,null as QUANTITY ,null as GROSS_SALES_BEFORE_TAX ,null as DISCOUNT ,null as TAX ,null as SHIPPING_PRICE ,null as SELLING_PRICE ,null as MRP_SALES ,null as OMS_ORDER_STATUS ,null as SHIPPING_STATUS ,null as FINAL_SHIPPING_STATUS ,null as SALEORDERITEMCODE ,null as SALES_ORDER_ITEM_ID ,null as AWB ,null as PAYMENT_GATEWAY ,coalesce(upper(PAYMENT_MODE),(case when replace(lower(payment_gateway),\' \',\'\') = \'cashondelivery\' then \'COD\' else \'PREPAID\' end))PAYMENT_MODE ,null as COURIER ,null as DISPATCH_DATE ,null as DELIVERED_DATE ,null as DELIVERED_STATUS ,null as RETURN_FLAG ,null as RETURNED_QUANTITY ,null as RETURNED_SALES ,null as CANCELLED_QUANTITY ,null as DAYS_IN_SHIPMENT ,null as ACQUSITION_DATE ,null as SKU_CODE ,PRODUCT_NAME_FINAL ,PRODUCT_CATEGORY ,null as PRODUCT_SUB_CATEGORY ,null as BRAND ,null as WAREHOUSE ,null as PINCODE ,null as EASYECOM_STATUS ,null as LINE_ITEM_SALES ,null as REFUND_AMOUNT_WITHOUT_LINEITEM ,null as DISCOUNT_CODE ,null as FINAL_STATUS ,NEW_CUSTOMER_FLAG ,null as NEW_CUSTOMER_FLAG_MONTH ,null as ACQUISITION_PRODUCT ,null as ACQUISITION_SKUCODE ,null as ACQUISITION_PRODUCT_SUB_CATEGORY ,null as ACQUISITION_PRODUCT_CATEGORY ,null as ACQUISITION_CHANNEL ,null as ACQUISITION_MARKETPLACE ,(ifnull(refund_amount_without_lineitem,0)+ifnull(Refund_Value,0)) as Return_Sales ,REFUND_QUANTITY as REFUND_QUANTITY ,\'Returns\' as Type ,case when uppeR(ifnull(ORDER_STATUS,\'\')) like \'%CANCEL%\' then \'YES\' else \'NO\' end as Cancelled_Status from ( select * from datalake_db.kaya.dwh_SHOPIFY_FACT_ITEMS b left join (select * from (select order_id ,city ,state ,saleorderitemcode ,sales_order_item_id ,shippingpackagecode ,SHIPPINGPACKAGESTATUS ,Courier ,awb ,Courierstatus ,payment_method ,PAYMENT_MODE ,row_number() over (partition by order_id, split_part(saleorderitemcode,\'-\',0) order by shipping_last_update_date desc) rw from datalake_db.kaya.dwh_UNICOMMERCE_FACT_ITEMS where lower(marketplace) like any (\'%shopify%\')) where rw=1 ) d on b.order_id=d.order_id and b.line_item_id=split_part(d.saleorderitemcode,\'-\',0) left join ( select order_id,new_customer_flag from datalake_db.kaya.dwh_sales_consolidated qualify row_number() over(partition by lower(order_id) order by 1) = 1 )ncf on lower(b.order_id) = lower(ncf.order_id) where not(lower(ifnull(order_status,\'\')) like \'%cancel%\') and (ifnull(refund_amount_without_lineitem,0)+ifnull(Refund_Value,0)) > 0 ) ; Create Or Replace table datalake_db.kaya.dwh_sales_consolidated as Select sc.* ,div0(ifnull(Targets,0) , count(*) over(partition by last_day(sc.order_date),lower(sc.marketplace),lower(sc.Cancelled_Status))) Targets from datalake_db.kaya.dwh_sales_consolidated SC left join ( select last_day(TO_DATE(month, \'YYYY-MM-DD\')) as Month, cast(replace(\"GMV Targets\",\',\',\'\') as float) AS Targets , \'NO\' as Cancelled_Status , \'SHOPIFY_KAYA\' as Marketplace from datalake_db.kaya.trn_dtc_monthly_targets )TR on last_day(sc.order_date) = tr.month and lower(sc.marketplace) = lower(tr.Marketplace) and lower(sc.Cancelled_Status) = lower(tr.Cancelled_Status) ;",
